questions.code:
html { font-size: 16px; }
.card {
  font-size: 20px;
  padding: 1em;
  margin-block: 1.5rem;
}

.card {
  box-sizing: border-box;
  width: 240px;
  padding: 20px;
  border: 4px solid royalblue;
  margin: 12px;
}

.menu {
  writing-mode: horizontal-tb;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: flex-start;
}

.layout { display: grid; }
@media (min-width: 48rem) {
  .layout { grid-template-columns: 2fr 1fr; }
}
